using System.Windows; using BookmarkModel=JASS.Bookmark.Master.Models.Bookmark;
namespace JASS.Bookmark.Master;
public partial class ResourceDetails:Window
{ public bool EditRequested{get;private set;} public BookmarkModel Bookmark{get;} public ResourceDetails(BookmarkModel b){InitializeComponent();Owner=Application.Current.MainWindow;Bookmark=b;Refresh();} void Refresh(){TitleText.Text=Bookmark.Title;TypeText.Text=Bookmark.ResourceType;UrlText.Text=Bookmark.Url;FolderText.Text=Bookmark.Folder;TagsText.Text=string.IsNullOrWhiteSpace(Bookmark.Tags)?"—":Bookmark.Tags;DescriptionText.Text=string.IsNullOrWhiteSpace(Bookmark.Description)?"—":Bookmark.Description;NotesText.Text=string.IsNullOrWhiteSpace(Bookmark.Notes)?"—":Bookmark.Notes;MetaText.Text=$"Added: {Bookmark.DateAdded}    Source: {Bookmark.Source}    Favorite: {(Bookmark.Favorite?"Yes":"No")}    Read Later: {(Bookmark.ReadLater?"Yes":"No")}";} void Edit_Click(object s,RoutedEventArgs e){EditRequested=true;Close();} void Close_Click(object s,RoutedEventArgs e){Close();}}
